import{_ as s,O as a,o as r,c as i,a as o,i as n,f as l}from"./chunks/framework.fmIt2z2h.js";const f=JSON.parse('{"title":"D.10　伦理分歧、能力与有限责任","description":"","frontmatter":{"title":"D.10　伦理分歧、能力与有限责任","xkChars":680,"xkLessons":{"D.10":{"title":"D.10　伦理分歧、能力与有限责任","lead":"即使各方同意某项安排会产生多少收益、谁会受损，也可能仍不同意它是否可被允许。公开分歧的规范前提，比捏造一个必然失败的未来更诚实；资源、机会、选择、生活结果和责任也须分开。","explanation":["原文定位：第4673—4688行；原文锚点 section-d-10；短引文：‘相同事实可以留下真实规范分歧，不必假造经验效果来消除分歧。’。本题源切片逐字另附于source-slice.md，讲解与原文分开。","德性伦理关注实践判断与行动者如何生活，义务论强调不能仅把人当作手段等约束，后果论比较收益和损害。这是本节用来引出问题的粗定位，不是完整定义，更不表示各传统内部毫无分歧。分析应将不同理由放入同一个具体问题，说明各自允许什么、禁止什么，而非先宣布某传统普遍获胜。","经验事实可以限制规范论证，却未必独自消除分歧。两方可能都承认某安排总收益较高，其中一方仍认为它违反独立的基本地位要求。此时不能为了支持反对意见而凭空声称安排迟早经济崩溃；也不能由短期高效推出它正当。规范限制可以独立提出，须说明理由和适用边界。","资源、可实现能力、实际选择和生活结果之间存在转换条件。同样的钱对有不同照护责任、残障支持、交通和制度条件的人，不一定形成相同可行机会。相同结果也可能来自截然不同选择余地。比较时应问拥有何种真实选择，而不只统计投入或最终活动，也不能把人实际没选某项就当成没有能力。","多个单项最大能力不一定可同时实现。例如给定同一天的时间，可用来学习或照护，各自单项上限很高，但不能把各上限拼成同一天同时可达的生活。应保留可行组合以及相互约束。一个能力表列出很多可能活动，不证明这些活动能够同时完成，更不意味着当事人必须全部实现。","愿意接受、可负担和没有其他选项是不同状态。有人在紧迫需要下接受安排，可能仅说明相对现有替代它可行，不代表负担轻、公平或自由选择条件完善。判断需要查替代方案、风险、时间与实际拒绝空间，不能由接受事实自动判定无需进一步讨论规范问题。","人际效用相加需要说明单位可比性与权重，写得出加权和并不自动决定谁的一单位相当于谁的一单位，也不决定允许哪些损失被抵销。数值表示是表达选择前提的工具，不是生成这些前提的机器。敏感性分析可以展示换权重后结论变动，不能把选定权重隐藏成唯一客观尺度。","潜在可补偿与实际补偿尤其不能混淆。总收益超过总损失，只说明在特定可转移资源假设下可能存在补偿方案；若没有真实支付、合适接收或损害本就不可完全替代，受损者仍承担损失。不能将获益者原则上付得起写成补偿已经完成，也不能由货币净增证明所有生活损失均可抵销。","自由可按当前干涉多少理解，也可关心是否受制于任意权力。后一种非支配视角不是从物理状态自动读出的事实，而是一种需公开辩护的规范选择。一个有权随时任意干涉的人暂时没干涉，与没有这种任意控制关系，在该视角下不同；分析要说明评价准则，不能混写成一个不证自明的统一自由量。","文化差异不能自动撤销共同保护，保护主张也需回应生活实践与实施代价。两边都不能凭标签结束讨论：不能仅说这是传统就忽略受损者，也不能只宣布普遍原则而不看具体实现条件、当事人声音与风险。价值保护、实施方式与经验效果各有论证责任。","责任应拆成行为归属、过错、因果贡献、受益、预防能力与补救。某机构有能力帮助，不因此负无限责任；没有过错，也不自动排除基于独立理由的救济安排。责任项目可以不同方向成立，不能用一个责任总标签把能力、事实和义务一次结案。具体法律责任不由本框架代判。","悲剧性选择可能不存在无损方案。即使有限程序义务已履行，不可逆的生活损失仍可能存在；应记录哪些要求未被满足、哪些损害不能修复、后续谁依何理由承担什么。把损失从指标中删掉不会让选择更负责任。八个入口依次是三大伦理传统、功利与通约性、Rawls及正义争论、Sen与Nussbaum能力方法、自由非支配共同体、人权文化普遍性、责任补救代际生态正义，以及困境悲剧不可比；本讲不冒称这些内部争论已经由目录解决。"],"distinctions":[{"leftTitle":"事实分歧","leftText":"对发生何事及后果大小意见不同。","rightTitle":"规范分歧","rightText":"即使同意事实，许可范围和基本地位限制仍可不同。"},{"leftTitle":"拥有资源","leftText":"钱物或服务投入。","rightTitle":"真实可行能力","rightText":"还取决于照护交通身体支持与制度转换条件。"},{"leftTitle":"单项上限","leftText":"每个维度分别能达到的最大值。","rightTitle":"联合可行组合","rightText":"多个上限可能不能同时实现，应保留约束。"},{"leftTitle":"潜在可补偿","leftText":"在假设下有足够资源设计补偿。","rightTitle":"已经补偿","rightText":"实际转移与损失承接须核，且有损失不可替代。"},{"leftTitle":"有限义务履行","leftText":"按所说明规范完成了某些程序或行为。","rightTitle":"生活损失消失","rightText":"不可逆损失仍可能存在，不能自动宣布全部修复。"}],"boundaries":["不以未经支持的未来低效证明所有不正当安排必然失败。","效用加总必须公开跨人单位、权重和不可抵销约束；数学表示不自行授权。","能力不生成无限义务，缺少过错不自动排除有独立理由的救济。","本讲不裁定真实个案法律责任、资格或强迫补偿。","以下数值全为教学构造，非社会福利估计或对具体人价值的定价。"],"questions":["同意全部事实后为何仍可能有分歧？","两个单项最大能力为何可能不能同时实现？","没有过错是否必然没有任何救济理由？","为什么加权和不能决定权重？"],"diagramPath":"/reading-assets/S-D-10/figures/section-d-10.png","caseLinks":[{"title":"真实官方历史说明：共同保护主张与实际实现分开","href":"https://europe.ohchr.org/universal-declaration-human-rights"}],"caseNotes":[{"title":"真实官方历史说明：共同保护主张与实际实现分开","text":"OHCHR驻欧盟代表处的《世界人权宣言》页面说明，这一文件由不同法律和文化背景的代表起草，提出普遍保护基本人权；“The original records”段载明1948年12月10日在巴黎获联合国大会通过。这里可确认一个公开共同保护主张及其通过事件，但不能把通过等同各地已经实现，也不能由该页面替任何具体权利冲突判案。","sourceLabel":"OHCHR驻欧盟代表处官方介绍","sourceUrl":"https://europe.ohchr.org/universal-declaration-human-rights","sourceLocator":"主标题后介绍段（行59）；The original records首段（行74）","boundary":"仅核官方历史介绍，不冒称已读全部原始会议记录、决议正文或所有国家实施材料；不解释当代法律效力，不给个案法律建议。","href":"https://europe.ohchr.org/universal-declaration-human-rights"}],"sourceRefs":[{"section":"D.10","start_line":4673,"end_line":4688,"startLine":4673,"endLine":4688}],"outputId":"section-d-10","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["固定同一个具体事实情境，分别公开德性、义务、后果等规范理由。","区分资源、能力、选择、生活结果，检查转换条件与真实可行组合。","公开跨人尺度、权重、抵销限制，分别登记潜在补偿和实际接续。","拆开行为归属过错因果受益预防补救，各自说明材料与独立规范理由。","记录无损方案不存在时的未满足要求和不可逆损失，不靠假造低效或删指标化解分歧。"],"teachingExamples":[{"title":"数学教学构造：单项最大值不能拼成生活","text":"设一天可分配10小时，学习x与照护y满足x≥0、y≥0、x+y≤10。分别最大化x可得10，最大化y也可得10，但(10,10)需要20小时，不可行。联合能力集合必须保留三角约束，不能用两个边际上限构造不存在的组合。","assumptions":"时间可连续分配、忽略其他活动，单纯有限资源模型。","boundary":"不规定真实人应把一天如何分配，也不意味着照护与学习总能如此拆分。"},{"title":"数学教学构造：净增不等于已补偿","text":"假设某安排令甲得100单位可转移资源、乙损60单位，净增40。若甲实际转给乙0，乙仍损60；若转60，甲余40、乙资源损失归零。后一结论还依赖所有相关损失均由同类资源完整补偿的强假设，真实生活未必满足。","assumptions":"金额单位纯构造，补偿可执行与可转移为额外假设。","boundary":"潜在转移不等实际支付，更不为不可逆损害定价。"},{"title":"数学教学构造：同事实不同规范许可","text":"假设安排A给两人资源结果(12,0)，B给(5,5)，且每人最低4被某规范设为不可抵销底线。只最大化等权总量会选A的12而非B的10；加上该底线则A不可许可，B可行。两种结论来自公开规范差异，不必改变资源事实或捏造A未来会崩溃。","assumptions":"只为展示总量与底线规则的差别；数字与底线均由作者设定。","boundary":"不证明底线4是现实正确值，也不将资源当全部福利或基本地位的完整代理。"},{"title":"教学构造：救济理由不必等于过错","text":"假想机构没有造成某次意外，却依据明确自愿设立的救济安排承接有限帮助。可讨论该安排的独立理由、资源与边界，不能为了证明可以救济而虚构其过错，也不能因有能力就要求无限承担。","assumptions":"虚构机构与安排，不涉及实际承诺或资金。","boundary":"具体义务需相应规范与授权，例子不代判法律责任。"}],"counterexamples":[{"identity":"source_counterexample","text":"安排很不正当，因此它必然很快低效崩溃。","effect":"规范反对可以有独立理由，未来效果仍需经验依据。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"得益100大于损失60，所以受损者已经被补偿。","effect":"净增40不说明发生转移，实际损失与补偿条件应分别核。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"程序义务已经履行，因此所有不可逆损失都不存在。","effect":"义务履行与生活损失是不同判断，需诚实保留未恢复部分。","sourceIds":["theory"]}],"questionAnswers":[{"question":"同意全部事实后为何仍可能有分歧？","answer":"允许抵销的范围、基本地位约束、权重和责任理由可以不同，需要公开规范前提。","basis":"本节原文及上述公开推导"},{"question":"两个单项最大能力为何可能不能同时实现？","answer":"它们可能竞争同一时间资源，边际最大值的组合不属于联合可行集合。","basis":"本节原文及上述公开推导"},{"question":"没有过错是否必然没有任何救济理由？","answer":"不必然，救济可有其他独立理由，但应公开边界而非虚构过错或无限义务。","basis":"本节原文及上述公开推导"},{"question":"为什么加权和不能决定权重？","answer":"公式只表达已给定权重的结果，权重及跨人单位可比性需要另行辩护。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-D-10/figures/section-d-10.png","alt":"事实保持一致，规范理由公开，不捏造必然低效；资源到能力有条件，单项上限，不等于联合可行；加权和须公开，单位／权重，抵销的边界；潜在补偿，不等于实际补偿，不可逆损失仍保留；归属／过错／因果，受益／预防／补救，分项确定有限责任；无损方案可能不存在，履行程序义务，不抹除生活损失。作者依D.10绘制；数值与规范底线均为教学构造，不作真实法律或福利裁决。","caption":"作者依D.10绘制；数值与规范底线均为教学构造，不作真实法律或福利裁决。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。切换总量规则与独立底线、实际补偿是否发生、能力组合是否可行，显示分歧所在。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"官方历史说明展示共同规范主张与通过事件，不把规范存在代替实施成效或现实个案许可。"},"openQuestions":["未取得10.01—10.08全部原研究，不能依据目录替各传统解决内部争议。","本案例仅核官方历史说明，原始决议与会议记录未成功取得，未复核各地实施或当代法律效力。"],"taskId":"S-D-10","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第4673—4688行；每节精确范围见sourceRefs","claim_support":["D.10：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"ohchr-udhr-history","title":"Universal Declaration of Human Rights — OHCHR Europe","url":"https://europe.ohchr.org/universal-declaration-human-rights","source_type":"primary","version_or_date":"页面未标发布日期；所述历史事件1948-12-10","locator":"主标题后介绍段（行59）；The original records首段（行74）","claim_support":["不同法律文化背景代表起草及普遍保护主张；1948-12-10巴黎大会通过"],"limits":["未取得原决议与会议全文，不推断当代法律效力、各地实施或具体规范冲突答案。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-10/lecture.md","sourcesPath":"/reading-assets/S-D-10/sources.json","sourceSlicePath":"/reading-assets/S-D-10/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-10/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-10.md","filePath":"theory/appendix-d/d-10.md"}'),c={name:"theory/appendix-d/d-10.md"};function d(u,e,p,h,m,g){const t=a("SectionLesson");return r(),i("div",null,[e[0]||(e[0]=o("",1)),n(t,{section:"D.10"}),e[1]||(e[1]=l("div",{class:"theory-source"},null,-1))])}const x=s(c,[["render",d]]);export{f as __pageData,x as default};
